using CustomCulling;
using MapGeneration;
using UnityEngine;

public class VeryHighPerformance : MonoBehaviour
{
    // Built-in indirect-light calibration, checked across LCZ, HCZ, EZ and surface.
    // HCZ's dark materials need more fill than the pale LCZ/EZ walls. These are
    // look-development values, not HDRP exposure or native intensity conversions.
    // Roles still select black/their own night vision during a real blackout.
    public static readonly Color NormalColor = new Color(0.35f, 0.35f, 0.35f, 1f);
    public static readonly Color HeavyColor = new Color(0.5f, 0.5f, 0.5f, 1f);
    public static readonly Color VHColor = new Color(0.35f, 0.35f, 0.35f, 1f);

    public static bool LightsOff { get; private set; }

{
    get
    {
        if (LightsOff)
            return VHColor;

        // The camera's room also covers spectating. The lookup is a single
        // existing coordinate-dictionary query; it adds no lamps or scans.
        return MainCameraController.TryGetCurrentRoom(out RoomIdentifier room)
            && room != null && room.Zone == FacilityZone.HeavyContainment ? HeavyColor : NormalColor;
    }
}

